import javax.servlet.http.HttpServletRequest;

public class HttpRequestUtils {

    /**
     * Build the 'Content-Range' HTTP Header value.
     * @return 'Content-Range' value
     */
    public String buildContentRange(HttpServletRequest request) {
        long contentLength = request.getContentLengthLong();
        long range = -1; // Default, i.e., full content
        String clientRange = request.getHeader("Range");
        if (clientRange != null) {
            String[] parts = clientRange.split("-");
            if (parts.length == 2) {
                try {
                    range = Long.parseLong(parts[1]) + 1; // Range starts from 1
                } catch (NumberFormatException e) {
                    // Handle invalid range format
                }
            }
        }
        return "bytes " + range + "-" + contentLength + "/" + contentLength;
    }
}

