private Set<V> intersection(Set<V> set1, Set<V> set2) {
    Map<V, Integer> map1 = new HashMap<>();
    Map<V, Integer> map2 = new HashMap<>();

    // Count occurrences of each element in set1
    for (V element : set1) {
        map1.put(element, map1.getOrDefault(element, 0) + 1);
    }

    // Count occurrences of each element in set2
    for (V element : set2) {
        map2.put(element, map2.getOrDefault(element, 0) + 1);
    }

    // Find common elements and calculate their total count
    Set<V> intersection = new HashSet<>();
    for (V element : set1) {
        if (map2.containsKey(element)) {
            intersection.add(element);
            map2.put(element, map2.get(element) - 1);
        }
    }

    return intersection;
}

