import java.util.List;
import java.util.ArrayList;
import java.util.Arrays;

public class SuffixSumCalculator {

    /**
     * Computes a suffix sum of the {@code bounds}. Returns the computed suffix sum and the sum of all elements in the {@code bounds list}.
     * @param bounds list of integers.
     * @return computed pair of suffix sum list and a sum of all elements.
     */
    private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
        if (bounds == null || bounds.isEmpty()) {
            throw new IllegalArgumentException("Bounds list cannot be null or empty");
        }

        List<Integer> suffixSum = new ArrayList<>();
        long sum = 0;

        for (int i = bounds.size() - 1; i >= 0; i--) {
            suffixSum.add(sum);
            sum += bounds.get(i);
        }

        return new Pair<>(suffixSum, sum);
    }

    public static void main(String[] args) {
        SuffixSumCalculator calculator = new SuffixSumCalculator();
        List<Integer> bounds = Arrays.asList(1, 2, 3, 4, 5);
        Pair<List<Integer>, Long> result = calculator.computeSuffixSum(bounds);
        System.out.println(result.toString()); // Should print: [(5, 15), (4, 10), (3, 6), (2, 4), (1, 3)]
    }

    static class Pair<E, F> {
        private E first;
        private F second;

        public Pair(E first, F second) {
            this.first = first;
            this.second = second;
        }

        @Override
        public String toString() {
            return "(" + first + ", " + second + ")";
        }
    }
}

