import java.util.Arrays;
import java.util.List;

public class KeyUpperBoundCalculator {
    /**
     * Finds a minimum lower bound for every key.
     * @param keys a list of keys.
     * @return the computed key upper bound.
     */
    public static List<Integer> computeUpperBounds(List<String> keys) {
        if (keys == null || keys.isEmpty()) {
            return Arrays.asList();
        }

        List<Integer> lowerBounds = new ArrayList<>();
        String previousKey = keys.get(0);
        int currentLowerBound = 0;

        for (String key : keys) {
            if (key.compareTo(previousKey) < 0) {
                currentLowerBound = 0;
            }
            previousKey = key;
            lowerBounds.add(currentLowerBound + key.length());
        }

        return lowerBounds;
    }

    public static void main(String[] args) {
        List<String> keys = Arrays.asList("apple", "banana", "cherry", "date");
        List<Integer> result = computeUpperBounds(keys);
        System.out.println(result); // Output: [0, 5, 15, 22]
    }
}

