import java.util.HashSet;
import java.util.Set;

/**
 * Check whether the subgraph of <code>graph</code> induced by the given <code>vertices</code> is complete, i.e. a clique.
 * @param graph the graph.
 * @param vertices the vertices to induce the subgraph from.
 * @return true if the induced subgraph is a clique.
 */
private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    // Check if any of the given vertices are not in the graph
    if (vertices.stream().anyMatch(vertex -> !graph.containsVertex(vertex))) {
        throw new IllegalArgumentException("One or more vertices do not exist in the graph.");
    }

    // Check if the size of the induced subgraph equals the number of vertices
    Set<V> inducedVertices = new HashSet<>(vertices);
    for (V vertex : inducedVertices) {
        if (vertices.stream().filter(v -> graph.edgeCountMatching(v, vertex) < 2).count() > 0) {
            return false;
        }
    }

    return true;
}

