public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return new ArrayList<>();
    }
    if (path.startsWith("/")) {
        path = path.substring(1); // Ignore leading '/'
    }
    return decode ? decodePath(path) : decodePath(path, StandardCharsets.UTF_8);
}

private static List<PathSegmentImpl> decodePath(String path) {
    return decodePath(path, StandardCharsets.UTF_8);
}

private static List<PathSegmentImpl> decodePath(String path) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    StringBuilder segment = new StringBuilder();
    int i = 0, last = 0;

    while (i < path.length()) {
        if ((path.charAt(i) & 0xC0) == 0x80) {
            // Handle multibyte characters
            segment.append((char) ((path.charAt(i++) - 0xC0) << 6 | (path.charAt(i++) - 0x80)));
        } else {
            if (path.charAt(i) != '/') {
                if (segment.length() > 0) {
                    segments.add(new PathSegmentImpl(segment.toString()));
                    segment = new StringBuilder();
                }
                segment.append((char) path.charAt(i));
            } else {
                break;
