public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 2) {
        throw new IllegalArgumentException("Desired capacity must be greater than or equal to 2");
    }

    while (true) {
        int primeCandidate = nextPrimeCandidate(desiredCapacity);
        if (!isPrime(primeCandidate)) {
            continue;
        }

        return primeCandidate;
    }
}

private static int nextPrimeCandidate(int desiredCapacity) {
    // Start checking from the square root of desired capacity as the smallest prime candidate
    int candidate = (int) Math.ceil(Math.sqrt(desiredCapacity)) + 1;

    // Use 6k ± 1 to check for prime numbers efficiently
    while (true) {
        if ((candidate % 6 == 1 || candidate % 6 == 5) && isPrime(candidate)) {
            return candidate;
        }
        candidate += 6;
    }
}

private static boolean isPrime(int n) {
    if (n <= 1) {
        return false;
    }
    if (n <= 3) {
        return true;
    }
    if (n % 2 == 0 || n % 3 == 0) {
        return false;
    }

    int sqrtN = (int) Math.sqrt(n);
    for (int i = 5; i <= sqrtN; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) {
            return false;
        }
    }

    return true;
}

